def cache_sim(capacity, ttl, ops):
    cache = {}  # key -> (value, write_time)
    lru_order = []  # list of keys in LRU order (most recent at end)
    results = []

    def is_expired(key, current_time):
        if key not in cache:
            return True
        _, write_time = cache[key]
        return current_time >= write_time + ttl

    def remove_expired(current_time):
        # Remove all expired entries
        expired_keys = [k for k in cache if is_expired(k, current_time)]
        for k in expired_keys:
            del cache[k]
            lru_order.remove(k)

    def mark_most_recent(key):
        # Move key to end of lru_order (most recent position)
        if key in lru_order:
            lru_order.remove(key)
        lru_order.append(key)

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            remove_expired(t)

            # If key already exists, remove it from lru_order
            if key in cache:
                lru_order.remove(key)
            # If cache is full and key is new, evict LRU entry
            elif len(cache) >= capacity:
                lru_key = lru_order.pop(0)
                del cache[lru_key]

            # Add the new entry
            cache[key] = (value, t)
            mark_most_recent(key)

        elif op[0] == 'get':
            _, t, key = op
            remove_expired(t)

            if key in cache:
                value, _ = cache[key]
                mark_most_recent(key)
                results.append(value)
            else:
                results.append(-1)

    return results

